nextflow_process {

    name "Test Process RGI_BWT"
    script "../main.nf"
    process "RGI_BWT"
    topics "versions"
    tag "modules"
    tag "modules_nfcore"
    tag "rgi"
    tag "rgi/bwt"
    tag "rgi/cardannotation"

    test("rgi/bwt - minigut - test_fastq_gz") {
        def card
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            card = extract(modules_testdata_base_path + 'genomics/prokaryotes/metagenome/rgi/card-data.tar.bz2')
            run("RGI_CARDANNOTATION") {
                script "modules/nf-core/rgi/cardannotation"
                process {
                    """
                    input[0] = file('${card}')
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + '../../mag/test_data/test_minigut_R1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + '../../mag/test_data/test_minigut_R2.fastq.gz', checkIfExists: true),
                   ]
                ]
                input[1] = RGI_CARDANNOTATION.out.db
                input[2] = []
                """
            }
        }

        then {
            def outDir = file(process.out.tsv[0][1][0]).parentFile
            def mappingFile = outDir.listFiles().find {
                it.name.endsWith(".gene_mapping_data.txt")
            }

            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out, unstableKeys: ["tsv", "json"]),
                    mappingFile.readLines().sort()
                    ).match() },
            )
        }
    }

    test("rgi/bwt - minigut - test_fastq_gz - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [ [ id:'test', single_end:false ], [ file('test_1.fastq.gz'), file('test_2.fastq.gz') ] ]
                input[1] = []
                input[2] = []
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

